1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Step = {
8	  op: string;
9	  items: Item[];
10	};
11	
12	export type Customer = {
13	  yearsWithMHPCO: number;
14	};
15	
