29	const PROCESSING_FEE = 5;
30	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	  potion: 40,
35	  rune: 25,
36	  moonstone: 25,
37	};
38	
39	// Percentages are applied as the exact fraction `amount * percent / 100`
40	// rather than via a float factor such as `amount * 0.1`, which drifts.
41	const percentOf = (percent: number, amount: number): number =>
42	  (amount * percent) / 100;
43	
44	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
45	const CURSE_SURCHARGE_PERCENT = 50;
46	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
47	const HIGH_ENCHANTMENT_THRESHOLD = 5;
48	
49	const firstInsuranceSurchargeOn = (policyBasePremium: number): number =>
50	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
51	
52	const LOYALTY_DISCOUNT_PERCENT = 20;
53	const LOYALTY_YEARS_THRESHOLD = 2;
54	
55	const loyaltyDiscountOn = (
56	  policyBasePremium: number,
57	  customer: Customer,
58	): number =>
59	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
60	    ? percentOf(LOYALTY_DISCOUNT_PERCENT, policyBasePremium)
61	    : 0;
62	
63	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
64	
65	const followUpDiscountOn = (
66	  policyBasePremium: number,
67	  quotesAlreadyProcessed: number,
68	): number =>
69	  quotesAlreadyProcessed > 0
70	    ? percentOf(FOLLOW_UP_DISCOUNT_PERCENT, policyBasePremium)
71	    : 0;
72	
73	// Surcharges attached to a single item are a percentage of that item's own
74	// base premium from the price list (never of the policy base premium).
75	const surchargeForItem = (item: Item): number => {
76	  const cursePercent = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
77	  const highEnchantmentPercent =
78	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
79	      ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT
80	      : 0;
81	  return percentOf(
82	    cursePercent + highEnchantmentPercent,
83	    BASE_PREMIUM_BY_TYPE[item.type],
84	  );
85	};
86	
87	const itemSurchargesOf = (items: Item[]): number =>
88	  items.reduce((total, item) => total + surchargeForItem(item), 0);
89	
90	const BLOCK_SIZE = 3;
91	const BLOCK_BASE_PREMIUM = 60;
92	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
93	
94	const countByType = (items: Item[]): Map<string, number> => {
95	  const counts = new Map<string, number>();
96	  for (const item of items) {
97	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
98	  }
99	  return counts;
100	};
101	
102	// A group of exactly BLOCK_SIZE alike components forms a block and is charged
103	// a flat BLOCK_BASE_PREMIUM instead of the per-item price list rate. Main
104	// items never form a block.
105	const basePremiumForAlikeItems = (type: string, count: number): number =>
106	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
107	    ? BLOCK_BASE_PREMIUM
108	    : count * BASE_PREMIUM_BY_TYPE[type];
109	
110	const policyBasePremiumOf = (items: Item[]): number =>
111	  [...countByType(items)].reduce(
112	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
113	    0,
114	  );
115	
116	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
117	  const results = scenario.steps.map((step, quotesAlreadyProcessed) => {
118	    const policyBasePremium = policyBasePremiumOf(step.items);
119	    const premium =
120	      policyBasePremium +
121	      itemSurchargesOf(step.items) -
122	      loyaltyDiscountOn(policyBasePremium, scenario.customer) +
123	      firstInsuranceSurchargeOn(policyBasePremium) -
124	      followUpDiscountOn(policyBasePremium, quotesAlreadyProcessed) +
125	      PROCESSING_FEE;
126	    return { premium };
127	  });
128	
129	  return { results };
130	};
